use super::*;
use serde::{Serialize,Deserialize};
#[derive(Clone,Serialize,Deserialize)] #[serde(default)] pub(super) struct Preferences {pub uk:bool,pub grid:bool,pub snap:f32,pub mirror:bool,pub floating:bool,pub rulers:bool,pub keys:pro::Keys}
impl Default for Preferences {fn default()->Self{Self{uk:true,grid:true,snap:16.,mirror:false,floating:false,rulers:true,keys:Default::default()}}}
pub(super) struct Document {project:Project,saved:Project,path:Option<PathBuf>,undo:Vec<Project>,redo:Vec<Project>}
#[derive(Default)] pub(super) struct Ultimate {pub prefs:Preferences,pub loaded:bool,pub documents:Vec<Option<Document>>,pub active:usize,pub marquee:Option<egui::Pos2>,pub guides:Vec<[f32;2]>,pub camera_preview:bool,pub drag_parent:Option<Uuid>,pub recovery_checked:bool,pub recovery_offer:Option<PathBuf>,pub prefab_paths:HashMap<usize,PathBuf>}
fn settings_path()->PathBuf{std::env::var_os("APPDATA").or_else(||std::env::var_os("HOME")).map(PathBuf::from).unwrap_or_else(std::env::temp_dir).join("ForgeEngine").join("settings.json")}
fn write_settings(p:&Preferences)->Result<(),String>{let path=settings_path();std::fs::create_dir_all(path.parent().unwrap()).map_err(|e|e.to_string())?;std::fs::write(path,serde_json::to_vec_pretty(p).map_err(|e|e.to_string())?).map_err(|e|e.to_string())}
pub(super) fn init(e:&mut Editor){if e.ultimate.loaded{return;}e.ultimate.loaded=true;if let Ok(b)=std::fs::read(settings_path()){if let Ok(p)=serde_json::from_slice::<Preferences>(&b){e.uk=p.uk;e.tools.grid=p.grid;e.tools.snap=p.snap.clamp(1.,256.);e.pro.keys=p.keys.clone();e.ultimate.prefs=p;}}e.ultimate.documents.push(None); e.ultimate.recovery_offer=std::fs::read(settings_path().with_file_name("last_recovery.json")).ok().and_then(|b|serde_json::from_slice(&b).ok());}
fn switch(e:&mut Editor,index:usize){if index==e.ultimate.active{return;}let Some(d)=e.ultimate.documents.get_mut(index).and_then(Option::take)else{return;};let old=Document{project:std::mem::replace(&mut e.project,d.project),saved:std::mem::replace(&mut e.saved,d.saved),path:std::mem::replace(&mut e.path,d.path),undo:std::mem::replace(&mut e.undo,d.undo),redo:std::mem::replace(&mut e.redo,d.redo)};e.ultimate.documents[e.ultimate.active]=Some(old);e.ultimate.active=index;e.selected=None;e.pro.multi.clear();e.textures.clear();e.stamps.clear();e.pro.last_scan=None;e.preview=0.;e.preview_play=false;e.pro.last_backup=None;}
pub(super) fn toolbar(ui:&mut egui::Ui,e:&mut Editor)->bool{let mut changed=false;ui.horizontal_wrapped(|ui|{let names=e.ultimate.documents.iter().enumerate().map(|(i,d)|if i==e.ultimate.active{format!("{}{}",e.project.name,if e.saved!=e.project{" *"}else{""})}else{d.as_ref().map(|d|format!("{}{}",d.project.name,if d.saved!=d.project{" *"}else{""})).unwrap_or_default()}).collect::<Vec<_>>();for (i,n) in names.iter().enumerate(){if ui.selectable_label(i==e.ultimate.active,n).clicked()&&i!=e.ultimate.active{switch(e,i);changed=true;}}if ui.button("+ Scene").clicked(){let p=Project::default();e.ultimate.documents.push(Some(Document{project:p.clone(),saved:p,path:None,undo:vec![],redo:vec![]}));let next=e.ultimate.documents.len()-1;switch(e,next);changed=true;}if let Some(path)=e.ultimate.prefab_paths.get(&e.ultimate.active).cloned(){if ui.button("Save prefab document").clicked(){match serde_json::to_vec_pretty(&e.project.objects).map_err(|x|x.to_string()).and_then(|b|std::fs::write(&path,b).map_err(|x|x.to_string())){Ok(())=>{e.saved=e.project.clone();e.status="Prefab saved".into();},Err(x)=>e.status=x}}}if ui.button("Edit prefab").clicked(){if let Some(path)=rfd::FileDialog::new().add_filter("Prefab JSON",&["json"]).pick_file(){match std::fs::read(&path).map_err(|x|x.to_string()).and_then(|b|serde_json::from_slice::<Vec<Object>>(&b).map_err(|x|x.to_string())){Ok(objects)=>{let p=Project{objects,name:"Prefab workspace".into(),..Project::default()};e.ultimate.documents.push(Some(Document{project:p.clone(),saved:p,path:None,undo:vec![],redo:vec![]}));let next=e.ultimate.documents.len()-1;e.ultimate.prefab_paths.insert(next,path);switch(e,next);changed=true;},Err(x)=>e.status=x}}}if ui.button("Open in tab").clicked(){if let Some(path)=rfd::FileDialog::new().add_filter("Forge",&["json"]).pick_file(){match Project::load(&path){Ok(p)=>{e.ultimate.documents.push(Some(Document{project:p.clone(),saved:p,path:Some(path),undo:vec![],redo:vec![]}));let next=e.ultimate.documents.len()-1;switch(e,next);changed=true;},Err(err)=>e.status=err}}}});changed}
pub(super) fn preferences(ui:&mut egui::Ui,e:&mut Editor){ui.checkbox(&mut e.ultimate.prefs.mirror,"Swap side panels");ui.checkbox(&mut e.ultimate.prefs.rulers,"Rulers");ui.checkbox(&mut e.ultimate.camera_preview,"Camera bounds");if ui.button("Save workspace").clicked(){e.ultimate.prefs.uk=e.uk;e.ultimate.prefs.grid=e.tools.grid;e.ultimate.prefs.snap=e.tools.snap;e.ultimate.prefs.keys=e.pro.keys.clone();e.status=write_settings(&e.ultimate.prefs).map(|_|"Workspace saved".into()).unwrap_or_else(|x|x);}}
pub(super) fn prefab_ui(ui:&mut egui::Ui,e:&mut Editor){ui.horizontal(|ui|{if ui.button("Save prefab").clicked(){if let Some(id)=e.selected{if let Some(path)=rfd::FileDialog::new().set_file_name("object.prefab.json").save_file(){let objects=forge_engine::prefab(&e.project,id);match serde_json::to_vec_pretty(&objects){Ok(b)=>if let Err(err)=std::fs::write(path,b){e.status=err.to_string();},Err(err)=>e.status=err.to_string()}}}}if ui.button("Instance prefab").clicked(){if let Some(path)=rfd::FileDialog::new().pick_file(){match std::fs::read(path).map_err(|e|e.to_string()).and_then(|b|serde_json::from_slice::<Vec<Object>>(&b).map_err(|e|e.to_string())){Ok(v)=>{let v=forge_engine::instantiate(v);e.selected=v.first().map(|o|o.id);e.project.objects.extend(v);},Err(err)=>e.status=err}}}});}
pub(super) fn motion_ui(ui:&mut egui::Ui,o:&mut Object,time:f32){ui.collapsing("Motion / Рух",|ui|{if ui.button("+ Keyframe").clicked(){o.motion.keys.retain(|k|(k.time-time).abs()>0.001);o.motion.keys.push(forge_engine::Key{time,position:o.position,rotation:o.rotation,smooth:false,bezier:None});}let mut remove=None;for(i,k)in o.motion.keys.iter_mut().enumerate(){ui.horizontal(|ui|{ui.add(egui::DragValue::new(&mut k.time).range(0. ..=3600.));for v in &mut k.position{ui.add(egui::DragValue::new(v));}ui.add(egui::DragValue::new(&mut k.rotation));ui.checkbox(&mut k.smooth,"Ease");if ui.button("×").clicked(){remove=Some(i);}});}if let Some(i)=remove{o.motion.keys.remove(i);}let(r,_)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(20.),80.),egui::Sense::hover());let p=ui.painter_at(r);let end=o.motion.keys.iter().map(|k|k.time).fold(1.,f32::max);let max=o.motion.keys.iter().map(|k|k.position[0].abs()).fold(1.,f32::max);let pts=(0..=100).filter_map(|i|{let t=i as f32/100.*end;o.motion.sample(t).map(|(v,_)|egui::pos2(r.left()+r.width()*t/end,r.center().y-v[0]/max*r.height()*0.45))}).collect::<Vec<_>>();if pts.len()>1{p.add(egui::Shape::line(pts,egui::Stroke::new(2.,egui::Color32::LIGHT_BLUE)));}ui.checkbox(&mut o.motion.auto_state,"Auto Idle / Run / Jump");ui.horizontal(|ui|{ui.label("Pivot (normalized)");for v in &mut o.motion.pivot{ui.add(egui::DragValue::new(v).speed(0.01).range(-0.5..=0.5));}});let frame=o.animation.frame(time);let mut b=o.motion.hitboxes.get(&frame).copied().unwrap_or([0.,0.,o.size[0],o.size[1]]);let mut changed=false;ui.horizontal(|ui|{ui.label("Hitbox X Y W H");for v in &mut b{changed|=ui.add(egui::DragValue::new(v)).changed();}});if changed{o.motion.hitboxes.insert(frame,b);}});}
pub(super) fn rulers(p:&egui::Painter,r:egui::Rect,origin:egui::Pos2,z:f32){let c=egui::Color32::from_gray(125);let step=64.*z;let mut x=r.left()+(origin.x-r.left()).rem_euclid(step);while x<r.right(){p.line_segment([egui::pos2(x,r.top()),egui::pos2(x,r.top()+8.)],egui::Stroke::new(1.,c));p.text(egui::pos2(x+2.,r.top()+8.),egui::Align2::LEFT_TOP,format!("{:.0}",(x-origin.x)/z),egui::FontId::monospace(10.),c);x+=step;}let mut y=r.top()+(origin.y-r.top()).rem_euclid(step);while y<r.bottom(){p.line_segment([egui::pos2(r.left(),y),egui::pos2(r.left()+8.,y)],egui::Stroke::new(1.,c));p.text(egui::pos2(r.left()+9.,y),egui::Align2::LEFT_CENTER,format!("{:.0}",(origin.y-y)/z),egui::FontId::monospace(10.),c);y+=step;}}

pub(super) fn recovery(ctx:&egui::Context,e:&mut Editor){
 if let Some(path)=e.ultimate.recovery_offer.clone(){if !path.exists(){e.ultimate.recovery_offer=None;return;}egui::Window::new("Recovery / Відновлення").collapsible(false).show(ctx,|ui|{ui.label(path.display().to_string());if ui.button("Recover in new tab / Відновити").clicked(){match Project::load(&path){Ok(p)=>{e.ultimate.documents.push(Some(Document{project:p.clone(),saved:Project::default(),path:Some(path.clone()),undo:vec![],redo:vec![]}));let next=e.ultimate.documents.len()-1;switch(e,next);e.ultimate.recovery_offer=None;},Err(err)=>e.status=err}}if ui.button("Dismiss / Закрити").clicked(){e.ultimate.recovery_offer=None;}});}
}
pub(super) fn mark_recovery(path:&std::path::Path){let f=settings_path().with_file_name("last_recovery.json");if let Some(dir)=f.parent(){let _=std::fs::create_dir_all(dir);}if let Ok(b)=serde_json::to_vec(path){let _=std::fs::write(f,b);}}
